/* eslint-disable max-lines */
import { t } from '@src/shared/i18n/utils';
import { Component, ComponentInterface, Element, h, Host, Prop, State, Watch, Method } from '@stencil/core';
import {
  FormListValidationStates,
  LabelAlign,
  NamePath,
  RuleItemExpand,
  STATUS_KEY,
  Trigger,
  ValidationSingleState,
  ValidationStates,
  type GeneralFormValue,
  type FormListValue,
} from '@src/components/ks-form/types';
import { Size, Status } from '@src/shared/base-props';
import { FormContext, FormContextValue, FormListUtils } from '@src/components/ks-form/context';
import { Consume, Provide } from '@src/framework/runtime-context';
import { immutableSet, move, parsePath } from '@src/components/ks-form/utils';
import type { KsFormItem } from '@src/components/ks-form-item';
import { assign } from 'lodash-es';
import { formMessages } from '@fe-infra/keystone-locales';
import { Slot, Slots } from '@src/framework/decorators';

const prefix = 'form-list';

/**
 * @slot default - Form list fields and related content rendered inside the form list.
 * @slot label - Allows customization of the form list's label. If not provided, the `label` prop will be used as content.
 * @part base - The base container of the component.
 * @part label - The label element.
 * @part control - The list control container.
 * @part controlMessage - The validation message container.
 */
@Component({
  tag: 'ks-form-list',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsFormList implements ComponentInterface {
  @Element() el!: HTMLKsFormListElement;

  private _keyManager: {
    keys: Array<number>;
    id: number;
  } = {
    keys: [],
    id: 0,
  };

  private _mapValueToFields = (value: FormListValue) =>
    (value || []).map((_, index) => {
      let key = this._keyManager.keys[index];
      if (key === undefined) {
        this._keyManager.keys[index] = this._keyManager.id;
        key = this._keyManager.keys[index];
        this._keyManager.id += 1;
      }

      return {
        name: index,
        key,
      };
    });

  private add: FormListUtils['add'] = (defaultValue?: GeneralFormValue, index?: number) => {
    const newListValue = this.valueFromContext || [];

    if (index !== undefined && index >= 0 && index <= newListValue.length) {
      this._keyManager.keys = [
        ...this._keyManager.keys.slice(0, index),
        this._keyManager.id,
        ...this._keyManager.keys.slice(index),
      ];

      const newValue = [...newListValue.slice(0, index), defaultValue, ...newListValue.slice(index)];

      this.dispatchContextChange({
        ...this.context,
        value: newValue,
      });

      this.registerContextEffect(() => {
        this.callbacksFromContext.onValueChange(newValue, this._relativePath(), [
          ...this._prefixPath,
          ...this._relativePath(),
        ]);
        if (this.validationStateFromContext) {
          const newStates = [
            ...this.validationStateFromContext.slice(0, index),
            [],
            ...this.validationStateFromContext.slice(index),
          ] as FormListValidationStates;
          newStates[STATUS_KEY] = this.validationStateFromContext[STATUS_KEY];
          this.callbacksFromContext._onValidationStatesChange(newStates, this._relativePath());
        }
      });
    } else {
      this._keyManager.keys = [...this._keyManager.keys, this._keyManager.id];

      const newValue = [...newListValue, defaultValue];
      this.dispatchContextChange({
        ...this.context,
        value: newValue,
      });

      this.registerContextEffect(() => {
        this.callbacksFromContext.onValueChange(newValue, this._relativePath(), [
          ...this._prefixPath,
          ...this._relativePath(),
        ]);
        if (this.validationStateFromContext) {
          const newStates = [...this.validationStateFromContext, []] as FormListValidationStates;
          newStates[STATUS_KEY] = this.validationStateFromContext[STATUS_KEY];
          this.callbacksFromContext._onValidationStatesChange(newStates, this._relativePath());
        }
      });
    }
    this._keyManager.id += 1;
  };
  private remove: FormListUtils['remove'] = (index: number | number[]) => {
    const newListValue = this.valueFromContext || [];
    const indexSet = new Set(Array.isArray(index) ? index : [index]);

    if (indexSet.size <= 0) {
      return;
    } else {
      this._keyManager.keys = this._keyManager.keys.filter((_, keysIndex) => !indexSet.has(keysIndex));

      const newValue = newListValue.filter((_, valueIndex) => !indexSet.has(valueIndex));

      this.dispatchContextChange({
        ...this.context,
        value: newValue,
      });

      this.registerContextEffect(() => {
        this.callbacksFromContext.onValueChange(newValue, this._relativePath(), [
          ...this._prefixPath,
          ...this._relativePath(),
        ]);
        if (this.validationStateFromContext) {
          const selfStatus = this.validationStateFromContext[STATUS_KEY];
          let newStateValue = assign(new Array(newListValue.length).fill(null), this.validationStateFromContext);
          newStateValue = newStateValue.filter(
            (_, stateIndex) => !indexSet.has(stateIndex),
          ) as FormListValidationStates;
          newStateValue[STATUS_KEY] = selfStatus;
          this.callbacksFromContext._onValidationStatesChange(newStateValue, this._relativePath());
        }
      });
    }
  };
  private move: FormListUtils['move'] = (from: number, to: number) => {
    if (from === to) {
      return;
    }
    const newListValue = this.valueFromContext || [];
    if (from < 0 || from >= newListValue.length || to < 0 || to >= newListValue.length) {
      return;
    }
    this._keyManager.keys = move(this._keyManager.keys, from, to);

    const newValue = move(newListValue, from, to);
    this.dispatchContextChange({
      ...this.context,
      value: newValue,
    });

    this.registerContextEffect(() => {
      this.callbacksFromContext.onValueChange(newValue, this._relativePath(), [
        ...this._prefixPath,
        ...this._relativePath(),
      ]);
      if (this.validationStateFromContext) {
        const selfStatus = this.validationStateFromContext[STATUS_KEY];
        let newStateValue = assign(new Array(newListValue.length).fill(null), this.validationStateFromContext);
        newStateValue = move(newStateValue, from, to) as FormListValidationStates;
        newStateValue[STATUS_KEY] = selfStatus;
        this.callbacksFromContext._onValidationStatesChange(newStateValue, this._relativePath());
      }
    });
  };

  private _effects: (() => void)[] = [];
  private registerContextEffect = (effect: () => void) => {
    this._effects.push(effect);
  };
  private dispatchContextChange = (context: FormContextValue<FormListValue, KsFormList>) => {
    this.el.dispatchEvent(
      new CustomEvent('context-change', {
        detail: {
          context,
        },
      }),
    );
  };
  protected contextEffect = () => {
    this._effects.forEach((effect) => effect());
    this._effects = [];
  };

  /** Callback after component willLoad completes, used to notify form that path is ready */
  // eslint-disable-next-line @stencil-community/own-props-must-be-private
  public __propsReady: Promise<void> = new Promise((resolve) => {
    this.__propsReadyResolver = resolve;
  });
  private __propsReadyResolver!: () => void;
  // eslint-disable-next-line @stencil-community/own-methods-must-be-private
  public _relativePath({ name = this.name, _prefixPath = this._prefixPath } = {}): string[] {
    const path = parsePath(name);
    if (path.slice(0, _prefixPath.length).join('.') === _prefixPath.join('.')) {
      return path.slice(_prefixPath.length);
    } else {
      return path;
    }
  }

  @Provide({
    context: FormContext,
    callback: (instance: unknown) => {
      (instance as HTMLElement)?.dispatchEvent?.(new CustomEvent('context-change', { detail: instance }));
    },
  })
  private context: FormContextValue<FormListValue, KsFormList> = {
    _provider: 'formList',
    _prefixPath: [],
    disabled: undefined,
    value: [],
    validationStates: {
      [STATUS_KEY]: null,
    },
    callbacks: {
      onValueChange: (value, path: string[] = [], originalPath?: string[]) => {
        const newItemValue = immutableSet(this.context.value, path, value);
        originalPath = originalPath || [...this._prefixPath, ...this._relativePath()];
        this.callbacksFromContext?.onValueChange(newItemValue, this._relativePath(), originalPath);
      },
      onBlur: (originalPath?: string[]) => {
        originalPath = originalPath || [...this._prefixPath, ...this._relativePath()];
        this.callbacksFromContext?.onBlur(originalPath);
      },
      onValidation: async (path: string[] = []) => {
        await this.validate(path);
      },
      _onValidationStatesChange: (validationStates: ValidationStates, path = []) => {
        const newStates = immutableSet<ValidationStates>(this.context.validationStates, path, validationStates);
        this.callbacksFromContext?._onValidationStatesChange(newStates, this._relativePath());
      },
      onResetValidation: async (path: string[] = []) => {
        await this.resetValidate(path || []);
      },
      _onComponentConnect: (instance: KsFormList, path: string[] = []) => {
        this.callbacksFromContext?._onComponentConnect(instance, [...this._relativePath(), ...path]);
      },
      _onComponentDisconnect: (instance: KsFormList, path: string[] = []) => {
        this.callbacksFromContext?._onComponentDisconnect(instance, [...this._relativePath(), ...path]);
      },
      _onPathChange: (instance: KsFormList, pathFrom: string[], pathTo: string[]) => {
        this.callbacksFromContext?._onPathChange(instance, pathFrom, pathTo);
      },
      _registerWatch: (path, callback, shouldCallImmediately) =>
        this.callbacksFromContext?._registerWatch(path, callback, shouldCallImmediately),
    },
    listUtils: {
      add: this.add,
      remove: this.remove,
      move: this.move,
      _mapValueToFields: this._mapValueToFields,
    },
  };

  @Consume({
    context: FormContext,
    subscribe: true,
    path(this: KsFormList) {
      /* istanbul ignore next */
      return ['value', ...this._relativePath()];
    },
  })
  @State()
  valueFromContext?: FormContextValue<FormListValue>['value'];
  @Watch('valueFromContext')
  updateContextValue() {
    this.context = {
      ...this.context,
      value: this.valueFromContext,
    };
  }

  @Consume({
    context: FormContext,
    subscribe: true,
    path(this: KsFormItem) {
      /* istanbul ignore next */
      return ['validationStates', ...this._relativePath()];
    },
  })
  @State()
  validationStateFromContext?: FormListValidationStates;
  @Watch('validationStateFromContext')
  updateValidationState() {
    let status: FormContextValue<FormListValue>['status'];
    const states = this.validationStateFromContext?.[STATUS_KEY] || [];
    if (states.length) {
      if (states.some(({ status }) => status === 'error')) {
        status = 'error';
      } else if (states.some(({ status }) => status === 'warning')) {
        status = 'warning';
      } else if (states.some(({ status }) => status === 'success')) {
        status = 'success';
      } else {
        status = 'default';
      }
    } else {
      status = 'default';
    }
    this.context = {
      ...this.context,
      status,
      validationStates: this.validationStateFromContext,
    };
    this.validateMessages = (this.validationStateFromContext?.[STATUS_KEY] || []).filter(
      (message) => message.status === 'error' || message.status === 'warning',
    );
  }
  @State() validateMessages: ValidationSingleState[] = [];

  // eslint-disable-next-line @stencil-community/no-unused-watch
  @Watch('validateStatus')
  validateStatusChange() {
    if (this.validateStatus) {
      this.context = {
        ...this.context,
        status: this.validateStatus,
      };
    }
  }

  @Consume({
    context: FormContext,
    subscribe: true,
    path: ['_prefixPath'],
  })
  @State()
  _prefixPath: FormContextValue<FormListValue>['_prefixPath'] = [];
  @Consume({
    context: FormContext,
    subscribe: true,
    path: ['disabled'],
  })
  @State()
  disabledFromContext: FormContextValue<FormListValue>['disabled'];
  @Consume({
    context: FormContext,
    subscribe: true,
    path: ['labelAlign'],
  })
  @State()
  labelAlignFromContext: FormContextValue<FormListValue>['labelAlign'];
  @Consume({
    context: FormContext,
    subscribe: true,
    path: ['labelWidth'],
  })
  @State()
  labelWidthFromContext: FormContextValue<FormListValue>['labelWidth'];

  @Watch('disabledFromContext')
  @Watch('labelWidthFromContext')
  @Watch('labelAlignFromContext')
  watchContextPropsChange() {
    this.context = {
      ...this.context,
      _prefixPath: [...this._prefixPath, ...this._relativePath()],
      disabled: this.disabledFromContext,
      labelWidth: this.labelWidthFromContext,
      labelAlign: this.labelAlignFromContext,
    };
  }

  @Watch('_prefixPath')
  prefixChange(newPrefix: string[], oldPrefix: string[]) {
    this.context = {
      ...this.context,
      _prefixPath: [...this._prefixPath, ...this._relativePath()],
    };
    this.callbacksFromContext?._onPathChange?.(
      this,
      [...oldPrefix, ...this._relativePath()],
      [...newPrefix, ...this._relativePath()],
    );
  }

  // eslint-disable-next-line @stencil-community/no-unused-watch
  @Watch('name')
  nameChange(newName: string, oldName: string) {
    this.context = {
      ...this.context,
      _prefixPath: [...this._prefixPath, ...this._relativePath()],
    };
    this.callbacksFromContext._onPathChange?.(
      this,
      this._relativePath({ name: oldName }),
      this._relativePath({ name: newName }),
    );
  }

  @Consume({
    context: FormContext,
    subscribe: false,
    path: ['callbacks'],
  })
  private callbacksFromContext!: FormContextValue<FormListValue>['callbacks'];

  /** The label text for the form item. */
  @Prop() label?: string;
  /** The width of the label in pixels. */
  @Prop() labelWidth?: number;
  /** The alignment of the label. Possible values are `left` and `right`. */
  @Prop() labelAlign?: LabelAlign;
  /** Indicates whether to display a colon after the label. When `true`, a colon is displayed after the label. */
  @Prop() colon = false;
  /** @deprecated The size of the form item. Possible values are `"xs"`, `"sm"`, `"md"`, `"lg"` and `"xl"`. */
  @Prop() size: Size = 'md';
  /**
   * The name of the field, which can be set as a chained property, such as:
   * - `name="user.name"`
   * - `name="name"`
   * - `name="arr[0].name"`
   * > Note: When using the chained property mode, it indicates that the field is a group, and the names of its subfields will be automatically appended to the parent field name, for example: `formModel = {user.name}`.
   * > If it is a non-chained property, the field name will be used directly, for example: `formModel = {name}`.
   */
  @Prop({ attribute: 'name' }) name!: NamePath;
  /** An array of validation rules for the form field. */
  @Prop() rules: RuleItemExpand[] = [];
  /** Indicates whether the form field is required. When `true`, the field must be filled out. */
  @Prop() required = false;
  /** The initial value of the form item. This value has a lower priority than the `initialValues` in `ks-form`. */
  @Prop() initialValue: FormListValue;
  /**
   * Used when there are dependencies between fields. If a field sets the `dependencies` property, it will automatically trigger validation when any of the dependent fields are updated.
   * A common scenario is the "Password" and "Confirm Password" fields in a user registration form.
   */
  @Prop() dependencies?: NamePath[];
  /** The validation status of the form field. Possible values are `default`, `"success"`, `"error"`, and `"warning"`. */
  @Prop() validateStatus?: Status;
  // /**
  //  * @locale {en} The event that triggers the form value change. Possible values are `blur` and `change`, default is `change`.
  //  * @locale {zh} 触发表单值改变的事件。可选值为 `blur`、`change`，默认为 `change`。
  //  */
  // @Prop() trigger: Trigger = 'change';
  /** The event(s) that trigger validation for the form field. Possible values are `blur` and `change`, default is `change`. */
  @Prop() validateTrigger: Trigger | Trigger[] = 'change';
  /** Options to show additional information or configuration for the field. */
  @Prop() showOption = true;

  /** The slot for customizing the label. */
  @Slot({ slotname: 'label' }) private labelSlot?: Slots;

  /**
   * INTERNAL FUNCTION
   * Collect rules for validation.
   */
  // eslint-disable-next-line @stencil-community/own-methods-must-be-private
  public _collectRules(trigger: Trigger | true) {
    let rulesWithRequired: RuleItemExpand[];
    if (this.required && !this.rules.find((r) => r.required)) {
      rulesWithRequired = [{ required: true }, ...this.rules];
    } else {
      rulesWithRequired = this.rules;
    }

    return rulesWithRequired.filter((r) => {
      if (trigger === true) {
        return true;
      }
      const triggerFromRule = r.trigger || this.validateTrigger;
      return triggerFromRule === trigger || (Array.isArray(triggerFromRule) && triggerFromRule.includes(trigger));
    });
  }

  private _disposers: Array<() => void> = [];
  private _registerDependencies() {
    // register dependencies for validation
    if (Array.isArray(this.dependencies)) {
      this.dependencies.forEach((dependency) => {
        const disposer = this.callbacksFromContext._registerWatch(parsePath(dependency), (_) => {
          this.validate().catch(() => {
            /* DO NOTHING */
          });
        });
        this._disposers.push(disposer);
      }, false);
    }
  }
  private _disposeDependencies() {
    this._disposers.forEach((disposer) => {
      disposer();
    });
  }

  connectedCallback(): void {
    this.__propsReady.then(() => {
      // on component connect callback
      this.callbacksFromContext?._onComponentConnect?.(this, this._relativePath());

      // register dependencies
      this._registerDependencies();
    });
  }

  disconnectedCallback(): void {
    this.callbacksFromContext._onComponentDisconnect?.(this, this._relativePath());
    this._disposeDependencies();
  }

  componentWillLoad(): Promise<void> | void {
    this.__propsReadyResolver();
    this.context = {
      ...this.context,
      _prefixPath: [...this._prefixPath, ...this._relativePath()],
      disabled: this.disabledFromContext,
      labelWidth: this.labelWidthFromContext,
      labelAlign: this.labelAlignFromContext,
      status: this.validateStatus,
    };
  }

  /**
   * @deprecated Please use `formRef.validate`
   * Validate the form field.
   */
  @Method()
  async validate(path: string[] = []) {
    await this.callbacksFromContext?.onValidation([...this._relativePath(), ...path]);
  }
  /**
   * @deprecated Please use `formRef.resetValidate`
   * Reset the validation status of the form field.
   */
  @Method()
  async resetValidate(path: string[] = []) {
    this.callbacksFromContext?.onResetValidation([...this._relativePath(), ...path]);
  }

  render() {
    const labelAlign = this.labelAlign || this.labelAlignFromContext;
    const labelWidth = this.labelWidth || this.labelWidthFromContext;
    const showOption = this.showOption && !this.required && !this._collectRules(true).find((item) => item.required);
    return (
      <Host class="KsFormList">
        <div
          class={{
            prefix: true,
            [`${prefix}--size-${this.size}`]: true,
          }}
          part="base"
        >
          {(this.label || this.labelSlot) && (
            <label
              class={{
                [`${prefix}__label`]: true,
                [`${prefix}__label--align-${labelAlign}`]: true,
              }}
              style={{ width: `${labelWidth}px` }}
              part="label"
            >
              <slot name="label">{this.label}</slot>
              {this.colon && ':'}
              {showOption && <span class={`${prefix}__label--optional`}>{` · ${t(formMessages.optional)}`}</span>}
            </label>
          )}
          <div class={`${prefix}__control`} part="control">
            <slot></slot>
            {(this.validateMessages.length && (
              <div class={`${prefix}__control__message`} part="controlMessage">
                {this.validateMessages.map((state) => {
                  if (state.status === 'error' || state.status === 'warning') {
                    return (
                      <span
                        class={{
                          [`${prefix}__control__message__text`]: true,
                          [`${prefix}__control__message__text--warning`]: state.status === 'warning',
                          [`${prefix}__control__message__text--error`]: state.status === 'error',
                        }}
                      >
                        <ks-status-message variant={state.status} richTextString={state.message} cta={state.cta} />
                      </span>
                    );
                  }
                })}
              </div>
            )) ||
              null}
          </div>
        </div>
      </Host>
    );
  }
}
